"""招聘工作台评分看板页面。

该页面是正式的只读查看器，而不是静态视觉稿：页面通过当前 Web 服务的招聘工作台
快照读取岗位、候选人、评估报告、分数分组和不合格原因。所有交互只改变浏览器中的
选中项，评分、人工确认和候选人状态仍由主工作台负责，避免预览页形成第二套业务逻辑。
"""

from __future__ import annotations

from html import escape


def render_score_board_preview(*, session_token: str = "") -> str:
	"""返回可直接打开的动态评分看板 HTML。

	HTML 内联样式和脚本，保持本地部署不依赖外部资源；脚本只调用同源 GET 接口，
	并使用 ``textContent`` 写入数据，防止候选人文本被当作 HTML 执行。
	"""
	return """<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>招聘工作台 · 候选人评分看板</title>
<style>
:root{font-family:Segoe UI,Microsoft YaHei,sans-serif;color:#18324b;background:#f4f7fa}
body{margin:0}.shell{max-width:1280px;margin:0 auto;padding:24px 22px 52px}
a{color:#0f766e;text-decoration:none}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:18px}.top h1{font-size:26px;margin:0 0 8px}.muted{color:#647689;margin:0}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.toolbar label{font-size:13px;color:#536b7e}.toolbar select{margin-left:8px;min-width:210px}.toolbar select,.back{border:1px solid #cbd8e4;background:#fff;border-radius:6px;padding:9px 11px}.grid{display:grid;grid-template-columns:minmax(330px,1.1fr) minmax(440px,1.9fr);gap:18px}.panel{background:#fff;border:1px solid #d6e1ea;border-radius:8px;padding:18px;box-shadow:0 3px 12px #1b46600d}.panel h2{font-size:17px;margin:0 0 14px}.candidate-list{display:grid;gap:9px}.candidate{display:block;width:100%;text-align:left;padding:13px 12px;border:1px solid #e1e9f0;border-radius:6px;background:#fff;cursor:pointer;font:inherit;color:inherit}.candidate:hover,.candidate.selected{border-color:#0f766e;background:#effaf8}.row{display:flex;justify-content:space-between;gap:10px}.name{font-weight:600}.score{font-weight:700;color:#0f766e}.badge{display:inline-block;font-size:12px;padding:3px 7px;border-radius:999px;background:#e8f5f1;color:#0f766e;margin-top:7px}.badge.warn{background:#fff5df;color:#9a6700}.badge.muted{background:#eef2f5;color:#607486}.hint{font-size:13px;color:#6b7d8e}.empty{padding:24px 4px;color:#6b7d8e}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{background:#f6f9fb;border-radius:6px;padding:12px}.metric strong{display:block;font-size:22px;margin-top:4px}.label{font-size:12px;color:#6b7d8e}.section{border-top:1px solid #e6edf2;margin-top:18px;padding-top:16px}.section h3{font-size:14px;margin:0 0 10px}.chips{display:flex;flex-wrap:wrap;gap:7px}.chip{background:#f0f5f7;border-radius:5px;padding:6px 8px;font-size:13px}.quote{margin:7px 0;padding:8px 10px;background:#f6f9fb;border-left:3px solid #8bb7ac;font-size:13px}.score-groups{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.score-group{padding:10px;background:#f6f9fb;border-radius:6px}.score-group strong{display:block;font-size:20px;color:#0f766e}.reason{display:flex;align-items:center;gap:10px;margin:10px 0}.reason b{width:128px;font-size:13px}.bar{height:9px;background:#dce9ef;border-radius:5px;flex:1;overflow:hidden}.bar i{display:block;height:100%;background:#ef8f65}.reason span{width:74px;text-align:right;font-size:13px;color:#617486}.notice{padding:11px 12px;background:#eef8f6;border-left:3px solid #0f766e;margin-top:12px;font-size:13px}.error{background:#fff1ee;border-left-color:#c2413b;color:#9f2d27}
@media(max-width:850px){.top{display:block}.toolbar{margin-top:14px}.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}
</style>
</head>
<body data-web-token="__WEB_TOKEN__"><main class="shell">
<header class="top"><div><h1>招聘工作台 · 候选人评分看板</h1><p class="muted">读取当前岗位的真实候选人评估；点击候选人查看评分依据、AI 分析和人工复核信息。</p></div><a class="back" href="/">返回招聘工作台</a></header>
<div class="toolbar"><label for="score-board-job">当前岗位</label><select id="score-board-job" aria-label="当前岗位"><option value="">正在读取岗位…</option></select><button id="score-board-auto-analyze" type="button">自动分析并分配本地简历</button><span id="score-board-auto-state" class="hint" aria-live="polite"></span><span id="score-board-state" class="hint" aria-live="polite">正在读取工作台数据…</span></div>
<section class="grid" aria-live="polite"><div class="panel"><h2>候选人列表</h2><div id="score-board-candidates" class="candidate-list"><div class="empty">正在读取候选人…</div></div><div class="section"><h3>候选人评分分组</h3><div id="score-board-groups" class="score-groups"></div></div></div>
<div class="panel"><h2 id="score-board-detail-title">评分解释</h2><div id="score-board-detail"><div class="empty">请选择候选人查看真实评估。</div></div><div class="section"><h3>当前岗位不合格原因统计</h3><div id="score-board-reasons"></div></div></div></section>
</main>
<script>
const jobSelect=document.querySelector('#score-board-job');
const stateNode=document.querySelector('#score-board-state');
const candidateList=document.querySelector('#score-board-candidates');
const groupsNode=document.querySelector('#score-board-groups');
const detailTitle=document.querySelector('#score-board-detail-title');
const detailNode=document.querySelector('#score-board-detail');
const reasonsNode=document.querySelector('#score-board-reasons');
const autoAnalyzeButton=document.querySelector('#score-board-auto-analyze');
const autoAnalyzeState=document.querySelector('#score-board-auto-state');
const webToken=document.body.dataset.webToken || '';
let snapshot={}; let selectedCandidateId=''; let activeJobId='';
const text=(value,fallback='（无）') => { const valueText=String(value ?? '').trim(); return valueText || fallback; };
const addText=(parent,tag,value,className='') => { const node=document.createElement(tag); if(className) node.className=className; node.textContent=text(value); parent.append(node); return node; };
const detailValue=value => { if(value && typeof value==='object') return value.message || value.summary || JSON.stringify(value); return text(value); };
const listOf=value => Array.isArray(value) ? value : [];
function selectedJobId() { return activeJobId || snapshot.selected_job_id || (snapshot.jobs || [])[0]?.job_id || ''; }
function reportFor(candidateId) { return (snapshot.assessments || []).find(item => item.candidate_id === candidateId) || null; }
function renderJobs() { jobSelect.replaceChildren(); const jobs=listOf(snapshot.jobs); if(!jobs.length) { addText(jobSelect,'option','暂无岗位'); jobSelect.disabled=true; return; } jobs.forEach(job => { const option=document.createElement('option'); option.value=job.job_id || ''; const suffix=job.platform_sync_status==='closed' ? '（已关闭，保留历史评估）' : (job.source==='manual' ? '（本地历史岗位）' : ''); option.textContent=text(job.name,'未命名岗位')+suffix; jobSelect.append(option); }); jobSelect.disabled=false; const current=selectedJobId(); if(current) jobSelect.value=current; }
function renderGroups() { groupsNode.replaceChildren(); const groups=listOf(snapshot.score_groups); if(!groups.length) { addText(groupsNode,'div','当前岗位暂无评分分组','empty'); return; } groups.forEach(group => { const box=document.createElement('div'); box.className='score-group'; addText(box,'span',group.label || group.range,'label'); addText(box,'strong',group.count || 0); groupsNode.append(box); }); }
function renderReasons() { reasonsNode.replaceChildren(); const stats=snapshot.rejection_reason_statistics || {}; const reasons=listOf(stats.reasons); if(!reasons.length) { addText(reasonsNode,'div','当前岗位尚无已评为不推荐的候选人。','empty'); return; } reasons.forEach(reason => { const row=document.createElement('div'); row.className='reason'; addText(row,'b',reason.label || reason.code); const bar=document.createElement('div'); bar.className='bar'; const fill=document.createElement('i'); fill.style.width=Math.max(0,Math.min(100,Number(reason.rate || 0)))+'%'; bar.append(fill); row.append(bar); addText(row,'span',`${reason.count || 0} 人 · ${reason.rate || 0}%`); reasonsNode.append(row); }); }
function renderCandidates() { candidateList.replaceChildren(); const candidates=listOf(snapshot.candidates); if(!candidates.length) { addText(candidateList,'div','当前岗位暂无候选人，可点击上方按钮自动分析桌面简历目录。','empty'); detailNode.replaceChildren(); addText(detailNode,'div','请选择候选人查看真实评估。','empty'); return; } if(!candidates.some(candidate => candidate.candidate_id === selectedCandidateId)) selectedCandidateId=candidates[0].candidate_id || ''; candidates.forEach(candidate => { const report=reportFor(candidate.candidate_id); const button=document.createElement('button'); button.type='button'; button.className='candidate'+(candidate.candidate_id===selectedCandidateId?' selected':''); button.addEventListener('click',() => { selectedCandidateId=candidate.candidate_id || ''; renderCandidates(); renderDetail(); }); const row=document.createElement('div'); row.className='row'; addText(row,'span',candidate.name || '未命名候选人','name'); addText(row,'span',report && report.final_score !== null && report.final_score !== undefined ? `${report.final_score} 分` : '未评估','score'); button.append(row); const assignment=report && report.auto_assignment; const level=candidate.resume_available===false ? '简历文件缺失' : (assignment && assignment.job_standard_ready===false ? '临时匹配，待完善标准' : (report ? (report.level || report.decision) : '未评估')); addText(button,'span',level,candidate.resume_available===false ? 'badge warn' : (assignment && assignment.job_standard_ready===false ? 'badge warn' : (report ? 'badge' : 'badge muted'))); candidateList.append(button); }); }
function renderDetail() { const candidate=listOf(snapshot.candidates).find(item => item.candidate_id===selectedCandidateId); const report=reportFor(selectedCandidateId); detailNode.replaceChildren(); if(!candidate) { detailTitle.textContent='评分解释'; addText(detailNode,'div','请选择候选人查看真实评估。','empty'); return; } detailTitle.textContent=`${text(candidate.name,'未命名候选人')} · 评分解释`; if(candidate.resume_available===false) addText(detailNode,'div','该候选人的历史简历文件已不在原路径；可保留既有评分供追溯，但不能重新读取或再次评分。','notice'); if(!report) { addText(detailNode,'div','该候选人尚未生成评估，请点击上方“自动分析并分配本地简历”。','notice'); return; } const metrics=document.createElement('div'); metrics.className='metrics'; [['综合评分',report.final_score],['评估等级',report.level],['评估引擎',report.engine],['人工确认',report.review_required?'待确认':'已确认']].forEach(item => { const box=document.createElement('div'); box.className='metric'; addText(box,'div',item[0],'label'); addText(box,'strong',item[1]); metrics.append(box); }); detailNode.append(metrics); const assignment=report.auto_assignment || {}; if(assignment.status) { const section=document.createElement('div'); section.className='section'; addText(section,'h3','自动岗位分配'); addText(section,'p',assignment.note || '已按最高匹配分自动分配。'); addDetailSection(section,'分配依据',[`评分来源：${assignment.score_basis==='job_standard'?'完整岗位标准':'职位名临时匹配'}`,`与次优岗位分差：${assignment.score_margin ?? 0} 分`,assignment.job_standard_ready===false?'岗位标准：待完善':'岗位标准：已完整'], '暂无自动分配信息'); detailNode.append(section); } const screening=report.screening || {}; const semantic=screening.semantic_match || {}; const hard=screening.hard_filter || {}; const risk=screening.risk || {}; const ai=report.ai_review || {}; addDetailSection(detailNode,'硬条件',listOf(hard.mismatches).concat(listOf(hard.unknowns)), '未发现硬条件问题'); addDetailSection(detailNode,'语义匹配',listOf(semantic.matched).concat(listOf(semantic.ai_matched).map(item => `AI 命中：${typeof item==='string'?item:item.criterion || ''}`), listOf(semantic.missing).map(item => `缺少：${item}`)), '暂无语义证据'); addDetailSection(detailNode,'风险信号',listOf(risk.signals).map(detailValue), '暂无已记录风险'); addDetailSection(detailNode,'带权评分依据',Object.entries(report.score_breakdown || {}).map(([key,value]) => { const row=value || {}; return `${key}：得分 ${row.score ?? '无'} · 权重 ${row.weight ?? '无'} · 加权 ${row.weighted_score ?? '无'}`; }), '暂无评分拆解'); if(ai.summary || listOf(ai.semantic_hits).length || listOf(ai.risk_findings).length || listOf(ai.follow_up_questions).length || listOf(ai.rejected_claims).length) { const section=document.createElement('div'); section.className='section'; addText(section,'h3','AI 语义分析'); if(ai.summary) addText(section,'p',ai.summary); listOf(ai.semantic_hits).forEach(hit => addText(section,'div',`${hit.criterion || '命中'}：${hit.quote || '无原文引用'}`,'quote')); listOf(ai.risk_findings).forEach(finding => addText(section,'div',`${finding.message || finding.code || '风险'}：${finding.quote || '无原文引用'}`,'quote')); if(listOf(ai.follow_up_questions).length) addText(section,'p','建议追问：'+ai.follow_up_questions.join('；')); if(listOf(ai.rejected_claims).length) addText(section,'p','未采信断言：'+ai.rejected_claims.join('；')); detailNode.append(section); } else { addText(detailNode,'div','当前为本地规则与已记录问答分析；配置 AI 并在 Research Mode 下重新评估后，这里会显示模型摘要和原文核对结果。','notice'); } }
function addDetailSection(parent,title,items,empty) { const section=document.createElement('div'); section.className='section'; addText(section,'h3',title); if(items.length) { const chips=document.createElement('div'); chips.className='chips'; items.forEach(item => addText(chips,'span',item,'chip')); section.append(chips); } else addText(section,'p',empty,'hint'); parent.append(section); }
async function loadSnapshot(jobId='') { const requestedJobId=jobId || activeJobId; stateNode.textContent='正在读取工作台数据…'; const suffix=requestedJobId ? `?job_id=${encodeURIComponent(requestedJobId)}` : ''; try { const response=await fetch('/api/recruiting/workspace'+suffix); const payload=await response.json(); if(!payload.ok) throw new Error(payload.error?.message || '工作台读取失败'); snapshot=payload.data || {}; activeJobId=snapshot.selected_job_id || requestedJobId; renderJobs(); renderGroups(); renderReasons(); renderCandidates(); renderDetail(); stateNode.textContent=`已读取 ${(snapshot.candidates || []).length} 位候选人`; } catch(error) { stateNode.textContent=error.message || '工作台读取失败'; candidateList.replaceChildren(); addText(candidateList,'div','无法读取当前岗位数据，请返回主工作台重试。','empty'); } }
async function waitForAutoAnalysis() { for(let attempt=0;attempt<120;attempt+=1) { await new Promise(resolve => setTimeout(resolve,250)); const response=await fetch('/api/state'); const payload=await response.json(); const state=(payload.data||{}).recruiting || {}; if(state.operation==='auto-assign-local-resumes' && state.state!=='running') return state; } throw new Error('本地分析仍在进行，请稍后刷新看板查看结果'); }
async function autoAnalyze() { autoAnalyzeButton.disabled=true; autoAnalyzeState.textContent='正在扫描并评分本地简历…'; try { const response=await fetch('/api/recruiting/candidates/auto-assign',{method:'POST',headers:{'Content-Type':'application/json','Origin':window.location.origin,'X-Boss-Web-Token':webToken},body:JSON.stringify({})}); const payload=await response.json(); if(!payload.ok) throw new Error(payload.error?.message || '自动分析启动失败'); autoAnalyzeState.textContent='本地分析正在进行…'; const state=await waitForAutoAnalysis(); if(state.state==='failed') throw new Error(state.error?.message || '本地分析失败'); await loadSnapshot(selectedJobId()); const result=state.result || {}; autoAnalyzeState.textContent=`已完成：扫描 ${result.scanned || 0} 份，自动分配 ${result.auto_assigned || 0} 份，待复核 ${result.unassigned || 0} 份。`; } catch(error) { autoAnalyzeState.textContent=error.message || '自动分析启动失败'; } finally { autoAnalyzeButton.disabled=false; } }
jobSelect.addEventListener('change',() => { activeJobId=jobSelect.value; loadSnapshot(activeJobId); }); autoAnalyzeButton.addEventListener('click',autoAnalyze); loadSnapshot();
</script></body></html>""".replace("__WEB_TOKEN__", escape(session_token, quote=True))
